Object.assign(uiWords,{'주행 보상과 퀘스트':['Flight rewards and quests','飛行報酬とクエスト','飞行奖励与任务'],'완주 기록':['Completion record','完走記録','通关记录'],'주행 기록':['Flight record','飛行記録','飞行记录']});
const progressDynamicTranslate=translateDynamic;
const progressSourceNames=[...new Set([...QUEST_TOTALS.map(d=>d.name),'누적 항해 거리',...BADGE_DEFS.map(d=>d.name)])];
function progressLanguage(){return {en:0,ja:1,zh:2}[settings.language];}
translateDynamic=function(text){
 if(settings.language==='ko')return text;
 const exact=tr(text);if(exact!==text)return exact;
 const n=progressLanguage(),pick=values=>values[n];let m;
 if((m=text.match(/^(.*) · (\d+)단계$/)))return tr(m[1])+pick([' · Tier '+m[2],' · '+m[2]+'段階',' · 第'+m[2]+'阶段']);
 if((m=text.match(/^(\d+) \/ (\d+) · 보상 ◈ (\d+)$/)))return m[1]+' / '+m[2]+pick([' · Reward ◈ ',' · 報酬 ◈ ',' · 奖励 ◈ '])+m[3];
 if((m=text.match(/^(.*) 진행도$/)))return tr(m[1])+pick([' progress',' 進行度',' 进度']);
 if((m=text.match(/^(\d{4}-\d{2}-\d{2}) · 매일 한국 시간 00시 초기화 · 전체 보상 160코인$/)))return m[1]+pick([' · Resets at 00:00 KST · 160 coins total',' · 毎日韓国時間0時リセット · 合計160コイン',' · 每日韩国时间0点重置 · 总奖励160金币']);
 if((m=text.match(/^모두 받기 · ◈ (\d+)$/)))return tr('모두 받기')+' · ◈ '+m[1];
 if((m=text.match(/^보상 수령 · ◈ (\d+)$/)))return pick(['Reward claimed','報酬受取','奖励已领取'])+' · ◈ '+m[1];
 if((m=text.match(/^(\d+)개 보상 수령 · 총 ◈ (\d+)$/)))return pick([m[1]+' rewards claimed · Total ◈ ',m[1]+'件受取 · 合計 ◈ ','已领取'+m[1]+'项奖励 · 共 ◈ '])+m[2];
 if((m=text.match(/^신규 (\d+)개 · 읽음 (\d+)개$/)))return pick(['New '+m[1]+' · Read '+m[2],'新着 '+m[1]+'件 · 既読 '+m[2]+'件','新通知 '+m[1]+'条 · 已读 '+m[2]+'条']);
 if((m=text.match(/^(신규|읽음) \((\d+)\)$/)))return tr(m[1])+' ('+m[2]+')';
 if((m=text.match(/^알림 · 읽지 않음 (\d+)개$/)))return tr('알림')+pick([' · '+m[1]+' unread',' · 未読'+m[1]+'件',' · '+m[1]+'条未读']);
 if((m=text.match(/^(데일리 완료|누적 퀘스트 완료|배지 획득) · (.+)$/)))return pick(m[1]==='데일리 완료'?['Daily complete','デイリー達成','每日任务完成']:m[1]==='누적 퀘스트 완료'?['Lifetime quest complete','累計クエスト達成','累计任务完成']:['Badge earned','バッジ獲得','获得徽章'])+' · '+m[2].split(' · ').map(tr).join(' · ');
 if((m=text.match(/^보상 ◈ (\d+)를 받을 수 있습니다\.$/)))return pick(['Claim ◈ '+m[1]+' now.','報酬 ◈ '+m[1]+'を受け取れます。','可领取奖励 ◈ '+m[1]+'。']);
 if((m=text.match(/^(\d+)단계 달성 · 보상 ◈ (\d+)$/)))return pick(['Tier '+m[1]+' complete · Reward ◈ ',m[1]+'段階達成 · 報酬 ◈ ','第'+m[1]+'阶段完成 · 奖励 ◈ '])+m[2];
 // Native summary labels are already localized; only the source quest/badge name needs translation.
 for(const name of progressSourceNames)if(text.endsWith(' · '+name))return progressDynamicTranslate(text.slice(0,-name.length))+tr(name);
 return progressDynamicTranslate(text);
};
